import { readFile, writeFile, mkdir } from "node:fs/promises";
import ts from "typescript";
import { format, resolveConfig } from "prettier";

// Canonical catalogues are read-only. Generated files are committed so tests
// and editors work without a preliminary build; --check detects stale output.
const directory = "src/app/data";
const check = process.argv.includes("--check");
const banner = "// Generated by scripts/shard_learning_content.mjs. Do not edit.\n";
const formatting = await resolveConfig(`${directory}/courseCatalog.ts`);
async function emit(name, source) {
  const target = `${directory}/${name}`;
  const output = await format(banner + source, { ...formatting, parser: "typescript" });
  const existing = await readFile(target, "utf8").catch(() => "");
  if (existing.replace(/\r\n/g, "\n") === output) return;
  if (check) throw new Error(`Stale learning content: ${target}`);
  await writeFile(target, output, "utf8");
}
function parse(name, source) {
  return ts.createSourceFile(name, source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
}
function declaration(file, name) {
  for (const statement of file.statements) {
    if (!ts.isVariableStatement(statement)) continue;
    const value = statement.declarationList.declarations.find(
      (item) => item.name.getText(file) === name
    );
    if (value) return { statement, value };
  }
  throw new Error(`Missing declaration: ${name}`);
}
function shardFor(id) {
  let hash = 0;
  for (const char of id.trim().toLowerCase().replace(/[-_]/g, "")) {
    hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
  }
  return hash % 64;
}
if (!check) await mkdir(`${directory}/contentChunks`, { recursive: true });

const lexiconSource = await readFile(`${directory}/lexiconDictionary.ts`, "utf8");
const lexiconFile = parse("lexiconDictionary.ts", lexiconSource);
const dictionary = declaration(lexiconFile, "LEXICON_DICTIONARY");
if (!ts.isObjectLiteralExpression(dictionary.value.initializer))
  throw new Error("Expected literal dictionary");
const shards = Array.from({ length: 64 }, () => []);
for (const entry of dictionary.value.initializer.properties) {
  if (!ts.isPropertyAssignment(entry)) throw new Error("Expected literal entry");
  shards[shardFor(entry.name.text)].push(entry.getText(lexiconFile));
}
for (const [index, entries] of shards.entries()) {
  await emit(
    `contentChunks/lexicon-${index}.ts`,
    `import type { LexiconEntry } from "../lexiconCore";\nexport const entries: Record<string, LexiconEntry> = {${entries.join(",\n")}};\n`
  );
}
const core = (
  lexiconSource.slice(0, dictionary.statement.getStart(lexiconFile)) +
  lexiconSource.slice(dictionary.statement.end)
)
  .replace(
    "export function getLexiconEntry(",
    "export function getLexiconEntry(\n  dictionary: Record<string, LexiconEntry>,"
  )
  .replaceAll("LEXICON_DICTIONARY", "dictionary");
await emit("lexiconCore.ts", core);

const lessonSource = await readFile(`${directory}/lessons.ts`, "utf8");
const lessonFile = parse("lessons.ts", lessonSource);
const removals = [];
const replacements = [];
const groupedWordIds = new Map();
const storyIndex = {};
for (const statement of lessonFile.statements) {
  if (!ts.isVariableStatement(statement)) continue;
  for (const value of statement.declarationList.declarations) {
    if (
      !value.name.getText(lessonFile).endsWith("_GROUPS") ||
      !value.initializer ||
      !ts.isArrayLiteralExpression(value.initializer)
    )
      continue;
    const stories = {};
    const wordIds = [];
    const shard = value.name.getText(lessonFile).toLowerCase().replaceAll("_", "-");
    for (const group of value.initializer.elements) {
      if (!ts.isObjectLiteralExpression(group)) throw new Error("Expected literal lesson");
      const words = group.properties.find(
        (property) => property.name?.getText(lessonFile) === "wordIds"
      );
      if (words && ts.isArrayLiteralExpression(words.initializer))
        wordIds.push(
          ...words.initializer.elements.map((item) => (ts.isStringLiteral(item) ? item.text : null))
        );
      const id = group.properties.find((p) => p.name?.getText(lessonFile) === "id");
      const story = group.properties.find((p) => p.name?.getText(lessonFile) === "story");
      if (!story) continue;
      if (!ts.isStringLiteral(id.initializer) || !ts.isStringLiteral(story.initializer))
        throw new Error("Expected literal story and id");
      if (storyIndex[id.initializer.text])
        throw new Error(`Duplicate story: ${id.initializer.text}`);
      stories[id.initializer.text] = story.initializer.text;
      storyIndex[id.initializer.text] = shard;
      let end = story.end;
      if (lessonSource[end] === ",") end++;
      removals.push([story.getStart(lessonFile), end]);
    }
    groupedWordIds.set(value.name.getText(lessonFile), wordIds);
    if (Object.keys(stories).length)
      await emit(
        `contentChunks/story-${shard}.ts`,
        `export const stories: Record<string, string> = ${JSON.stringify(stories)};`
      );
  }
}
// Reuse an identical group's ID list rather than shipping every ID twice.
// Values and ordering are proved equal before replacing; media fields are untouched.
const units = declaration(lessonFile, "COURSE_UNITS").value.initializer;
if (!ts.isObjectLiteralExpression(units)) throw new Error("Expected literal curriculum units");
for (const property of units.properties) {
  if (!ts.isPropertyAssignment(property) || !ts.isObjectLiteralExpression(property.initializer))
    continue;
  const fields = property.initializer.properties;
  const groups = fields.find((field) => field.name?.getText(lessonFile) === "groups");
  const words = fields.find((field) => field.name?.getText(lessonFile) === "wordIds");
  if (
    !groups ||
    !words ||
    !ts.isPropertyAssignment(groups) ||
    !ts.isPropertyAssignment(words) ||
    !ts.isIdentifier(groups.initializer) ||
    !ts.isArrayLiteralExpression(words.initializer)
  )
    continue;
  const original = words.initializer.elements.map((item) =>
    ts.isStringLiteral(item) ? item.text : null
  );
  const grouped = groupedWordIds.get(groups.initializer.text);
  if (!grouped || original.includes(null) || JSON.stringify(original) !== JSON.stringify(grouped))
    continue;
  replacements.push([
    words.initializer.getStart(lessonFile),
    words.initializer.end,
    `${groups.initializer.text}.flatMap((group) => group.wordIds)`,
  ]);
}
let catalogue = lessonSource;
for (const [start, end, replacement] of [
  ...removals.map(([start, end]) => [start, end, ""]),
  ...replacements,
].sort((a, b) => b[0] - a[0]))
  catalogue = catalogue.slice(0, start) + replacement + catalogue.slice(end);
await emit("courseCatalog.ts", catalogue);
await emit(
  "lessonStoryIndex.ts",
  `export const lessonStoryIndex: Record<string, string> = ${JSON.stringify(storyIndex)};`
);
console.log(
  `Learning content ${check ? "verified" : "prepared"}: 64 lexicon shards, ${Object.keys(storyIndex).length} lesson stories.`
);
